import {csvInLanguage,getLanguage} from './i18n.js?v=0.2.2-cm20261103-r2';
import './site-shell.js?v=0.2.2-cm20261103-r2';
import {brandGroup,familyKey,value,speedValue,isResearch,filterRecords,groupRecords,sortItems,numberText,boundText,runtimeText} from './catalog.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const paths={search:'<circle cx="10.8" cy="10.8" r="6.5"/><path d="m16 16 4 4"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 16v4h16v-4"/>',sliders:'<path d="M4 6h16M4 12h16M4 18h16"/><circle cx="8" cy="6" r="2" fill="currentColor"/><circle cx="16" cy="12" r="2" fill="currentColor"/><circle cx="10" cy="18" r="2" fill="currentColor"/>',x:'<path d="m6 6 12 12M6 18 18 6"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',list:'<path d="M8 5h13M8 12h13M8 19h13M3 5h1M3 12h1M3 19h1"/>','arrow-right':'<path d="M4 12h15m-5-5 5 5-5 5"/>','arrow-up-right':'<path d="M6 18 18 6M6 6h12v12"/>',plus:'<path d="M12 5v14M5 12h14"/>',check:'<path d="m5 12 4 4L19 6"/>',book:'<path d="M12 5c-3-2-6-2-9-1v15c3-1 6-1 9 1m0-15c3-2 6-2 9-1v15c-3-1-6-1-9 1V5Z"/>',layers:'<path d="m3 8 9-5 9 5-9 5-9-5Zm0 5 9 5 9-5M3 18l9 5 9-5"/>',link:'<path d="m10 14 4-4M8 16l-1 1a3.5 3.5 0 0 1-5-5l4-4a3.5 3.5 0 0 1 5 0m2 8a3.5 3.5 0 0 0 5 0l4-4a3.5 3.5 0 0 0-5-5l-1 1"/>',robot:'<path d="M4 8h12l4 4h-8l-3-2H4V8Zm2 3-2 6 3 4m6-9 2 5-2 4m4-9 4 5-1 4"/>',wheel:'<circle cx="5" cy="18" r="3"/><circle cx="19" cy="18" r="3"/><path d="M5 15 8 7h8l3 8M7 11h10"/>'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[n]??paths.book}</svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function safeUrl(url){try{const u=new URL(url);return ['https:','http:'].includes(u.protocol)?u.href:'#';}catch{return '#';}}
function injectIcons(root=document){root.querySelectorAll('[data-icon]').forEach(e=>e.outerHTML=icon(e.dataset.icon));}
injectIcons();
function storeGet(k,fallback){try{return localStorage.getItem(k)??fallback}catch{return fallback}}
function storeSet(k,v){try{localStorage.setItem(k,v)}catch{}}
const state={query:'',brands:new Set(),categories:new Set(),type:'all',massMin:null,massMax:null,payloadMin:null,speedMin:null,runtimeMin:null,scope:'families',view:storeGet('atlas-view','cards'),sort:'featured'};
if(!['cards','list'].includes(state.view))state.view='cards';
let data,records=[],byId=new Map(),currentResults=[],compareIds=[],detailId=null,detailTab='spec',toastTimer;
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,2600)}
function imageFor(p){return p.image??null}
function titleFor(p){if(p.id==='AN-ORIG')return 'ANYmal 早期研究型';if(p.id==='AN-W')return 'ANYmal 轮足';return p.family;}
function imageHtml(p,extra=''){const im=imageFor(p);return im?`<img src="${esc(im.path)}" alt="${esc(titleFor(p))}，${esc(im.credit)}图片" loading="lazy" decoding="async" ${extra}>`:`<div class="image-pending"><strong>${esc(p.family)}</strong><span>历史图像待补</span></div>`;}
function metricHtml(label,text,unit){return `<div><span class="metric-label">${esc(label)}</span><span class="metric-value ${text==='—'?'missing':''}">${esc(text)}${text==='—'?'':`<small>${esc(unit)}</small>`}</span></div>`;}
function displaySpeed(p){return boundText(p.metrics.speedPeak??p.metrics.speed)}
function evidenceBadge(p){return isResearch(p)?`<span class="evidence-tag research">${icon('book')}科研资料</span>`:`<span class="evidence-tag">${icon('check')}原厂资料</span>`;}
function compareControl(p,extra=''){const on=compareIds.includes(p.id);return `<button type="button" class="compare-add ${on?'selected':''} ${extra}" data-compare="${esc(p.id)}" aria-label="${on?'移除':'加入'}${esc(p.family+' '+p.variant)}参数对比" aria-pressed="${on}">${icon(on?'check':'plus')}</button>`;}
function card({record:p,variants}){
 const im=imageFor(p),allVariants=records.filter(r=>familyKey(r)===familyKey(p));
 return `<article class="robot-card" data-id="${esc(p.id)}">${compareControl(p)}<button type="button" class="card-open" data-open="${esc(p.id)}" aria-label="查看 ${esc(titleFor(p)+' '+p.variant)} 详情"><div class="card-media ${im?.photo?'photo':''}"><span class="type-tag ${p.type==='轮足'?'wheeled':''}">${icon(p.type==='轮足'?'wheel':'robot')}${esc(p.type)}</span>${imageHtml(p)}</div><div class="card-content"><p class="card-brand">${esc(p.brand)}</p><div class="card-title-line"><h3>${esc(titleFor(p))}</h3>${state.scope==='families'&&allVariants.length>1?`<span class="card-versions">${variants.length===allVariants.length?allVariants.length:variants.length+'/'+allVariants.length} 配置</span>`:''}</div><p class="card-subtitle" title="${esc(p.variant+' · '+p.position)}">${esc(p.variant)} · ${esc(p.position)}</p><div class="card-metrics">${metricHtml('整机质量',boundText(p.metrics.mass),'kg')}${metricHtml('公开载重',boundText(p.metrics.payload),'kg')}${metricHtml('最高披露速度',displaySpeed(p),'m/s')}${metricHtml('续航',runtimeText(p),'h')}</div><div class="card-bottom">${evidenceBadge(p)}<span class="card-detail-link">查看详情 ${icon('arrow-right')}</span></div></div></button></article>`;
}
function list(items){return `<div class="robot-list-wrap"><table class="robot-table"><thead><tr><th>平台 / 配置</th><th>厂商 / 机构</th><th>形态</th><th class="num">质量 kg</th><th class="num">公开载重 kg</th><th class="num">披露速度 m/s</th><th class="num">续航 h</th><th>对比 / 详情</th></tr></thead><tbody>${items.map(({record:p,variants})=>`<tr><td><button type="button" class="table-robot" data-open="${esc(p.id)}">${imageFor(p)?imageHtml(p):'<span class="table-placeholder"></span>'}<span><strong>${esc(titleFor(p))}</strong><small>${esc(p.variant)}${state.scope==='families'&&variants.length>1?' · '+variants.length+'配置':''}</small></span></button></td><td>${esc(brandGroup(p))}</td><td><span class="list-count">${esc(p.type)}</span></td><td class="num">${esc(boundText(p.metrics.mass))}</td><td class="num">${esc(boundText(p.metrics.payload))}</td><td class="num">${esc(displaySpeed(p))}</td><td class="num">${esc(runtimeText(p))}</td><td>${compareControl(p,'table-compare')}<button type="button" class="table-open-arrow" data-open="${esc(p.id)}" aria-label="查看${esc(p.family)}详情">${icon('arrow-right')}</button></td></tr>`).join('')}</tbody></table></div>`;}
function renderChips(){const chips=[];for(const b of state.brands)chips.push([`brand:${b}`,b]);for(const c of state.categories)chips.push([`category:${c}`,c==='research'?'科研平台':'商业 / 历史产品']);if(state.type!=='all')chips.push(['type',state.type]);for(const[k,label,u]of [['massMin','质量 ≥ ','kg'],['massMax','质量 ≤ ','kg'],['payloadMin','公开载重 ≥ ','kg'],['speedMin','披露速度 ≥ ','m/s'],['runtimeMin','续航下值 ≥ ','h']])if(state[k]!==null)chips.push([k,label+state[k]+' '+u]);if(state.query)chips.push(['query','搜索：'+state.query]);$('#activeFilters').hidden=chips.length===0;$('#activeFilters').innerHTML=chips.map(([k,v])=>`<button class="filter-chip" type="button" data-clear="${esc(k)}" aria-label="移除筛选 ${esc(v)}">${esc(v)}${icon('x')}</button>`).join('');}
function render(){if(!data)return;const matching=filterRecords(records,state);currentResults=sortItems(groupRecords(matching,state.scope),state.sort);$('#resultCount').textContent=currentResults.length;$('#matchingCount').textContent=`${matching.length} 条配置记录`;$('#resultsContent').className=state.view==='cards'?'robot-grid':'';$('#resultsContent').innerHTML=currentResults.length?(state.view==='cards'?currentResults.map(card).join(''):list(currentResults)):`<div class="empty-state">${icon('search')}<h3>没有符合条件的平台</h3><p>试着放宽指标范围，或移除部分筛选。缺失参数不会按 0 计算。</p><button class="button button-primary" type="button" data-reset>清除筛选</button></div>`;$$('[data-view]').forEach(e=>{const on=e.dataset.view===state.view;e.classList.toggle('active',on);e.setAttribute('aria-pressed',on)});$$('[data-scope]').forEach(e=>{const on=e.dataset.scope===state.scope;e.classList.toggle('active',on);e.setAttribute('aria-pressed',on)});$$('[data-type]').forEach(e=>{const on=e.dataset.type===state.type;e.classList.toggle('active',on);e.setAttribute('aria-pressed',on)});renderChips();}
function renderBrands(){const order=['Unitree','Boston Dynamics','ANYbotics','DEEP Robotics','Ghost Robotics','MIT','ETH Zurich','IIT','ODRI'];order.sort((a,b)=>groupRecords(records.filter(p=>brandGroup(p)===b)).length-groupRecords(records.filter(p=>brandGroup(p)===a)).length||a.localeCompare(b,'en'));$('#brandFilters').innerHTML=order.map(b=>{const count=groupRecords(records.filter(p=>brandGroup(p)===b)).length;return `<label class="check-row"><input type="checkbox" name="brand" value="${esc(b)}"><span>${esc(b)}</span><span class="brand-count">${count}</span></label>`}).join('');}
function reset(){Object.assign(state,{query:'',brands:new Set(),categories:new Set(),type:'all',massMin:null,massMax:null,payloadMin:null,speedMin:null,runtimeMin:null});$('#searchInput').value='';$$('input[name=brand],input[name=category]').forEach(e=>e.checked=false);['massMin','massMax','payloadMin','speedMin','runtimeMin'].forEach(k=>$('#'+k).value='');render()}
function removeChip(k){if(k.startsWith('brand:')){const v=k.slice(6);state.brands.delete(v);$$('input[name=brand]').find(e=>e.value===v).checked=false;}else if(k.startsWith('category:')){const v=k.slice(9);state.categories.delete(v);$$('input[name=category]').find(e=>e.value===v).checked=false;}else if(k==='query'){state.query='';$('#searchInput').value=''}else if(k==='type'){state.type='all'}else{state[k]=null;$('#'+k).value=''}render()}
function openFilters(open){$('#filterPanel').classList.toggle('open',open);$('#filterShade').hidden=!open;$('#openFilters').setAttribute('aria-expanded',open);if(open)$('#closeFilters').focus();else $('#openFilters').focus();}
function showDialog(id){const d=$('#'+id);if(!d.open)d.showModal();document.body.classList.add('dialog-open')}
function closeDialog(id){const d=$('#'+id);if(d.open)d.close();if(!$$('dialog').some(e=>e.open))document.body.classList.remove('dialog-open');if(id==='detailDialog'){detailId=null;history.replaceState(null,'',location.pathname+location.search)}}
function sourceIds(p){const ids=new Set([p.source,...Object.values(p.metrics).map(m=>m.source)]);return [...ids].filter(id=>data.sources[id])}
function specRow(p,key,label,unit,note=''){const m=p.metrics[key];return `<div class="spec-row"><span>${esc(label)}</span><strong class="${m?'':'missing'}">${esc(boundText(m))}${m?' '+esc(unit):''}</strong><small>${esc([note,m?.condition,m?.qual&&!['约','标称','>','<','≥','≤'].includes(m.qual)?m.qual:''].filter(Boolean).join('；')||(m?'原文未进一步细分测试条件':'该版本未披露或尚待核实'))}</small></div>`}
function specContent(p){return `<h3 class="detail-section-title">整机性能 <span>数值保留原文边界</span></h3><div class="spec-grid">${specRow(p,'mass','整机质量','kg',p.massBasis)}${specRow(p,'payload','公开标称 / 持续载重','kg')}${specRow(p,'length','长度','m',p.sizeBasis)}${specRow(p,'payloadMax','极限载重','kg','不当作持续载重')}${specRow(p,'width','宽度','m',p.sizeBasis)}${specRow(p,'static','站立静载','kg','与动态行走载重分开')}${specRow(p,'height','高度','m',p.sizeBasis)}${specRow(p,'speed','工作速度上限','m/s')}${specRow(p,'speedPeak','最高 / 演示速度','m/s')}${specRow(p,'runtimeMin','续航下值','h',p.runtimeBasis)}${specRow(p,'runtimeMax','续航上值','h',p.runtimeBasis)}${specRow(p,'battery','电池能量','Wh')}${specRow(p,'loadedMass','带载续航试验负载','kg')}${specRow(p,'loadedMin','带载续航下值','h')}${specRow(p,'loadedMax','带载续航上值','h')}${specRow(p,'range','空载 / 任务里程','km')}${specRow(p,'loadedRange','带载里程','km')}${specRow(p,'torque','最大披露单轴扭矩','N·m','不能视作所有关节连续额定')}${specRow(p,'dof','腿与轮主动轴数','个')}${specRow(p,'step','连续楼梯高度','m')}${specRow(p,'obstacle','单级越障高度','m')}${specRow(p,'slope','坡度','°')}<div class="spec-row"><span>防护等级</span><strong>${esc(p.ip)}</strong><small>等级适用范围以原厂配置说明为准</small></div><div class="spec-row"><span>开发接口与生态</span><strong style="font-family:inherit;font-size:10px;max-width:250px">${esc(p.access)}</strong><small>${esc(p.phase)}</small></div></div>${p.notes?`<div class="detail-note"><strong>这条记录的使用边界</strong>${esc(p.notes)}</div>`:''}<div class="source-pills">${sourceIds(p).map(id=>`<a href="${esc(safeUrl(data.sources[id].url))}" target="_blank" rel="noopener noreferrer">${esc(id)} 原始资料${icon('arrow-up-right')}</a>`).join('')}</div>`}
function jointContent(p){const js=data.joints.filter(j=>j.platform.split(';').includes(p.id));return `<h3 class="detail-section-title">关节与传动 <span>${js.length} 条关联记录</span></h3>${js.length?js.map(j=>`<article class="joint-record"><div class="joint-title"><small>${esc(j.id)}</small><h4>${esc(j.axis)}</h4></div><p>${esc(j.act)} · ${esc(j.drive)}</p><div class="joint-specs">${[['主减速比',j.ratio,':1'],['额外级比',j.remote,':1'],['最大输出',j.peak,'N·m'],['连续输出',j.cont,'N·m'],['速度上限',j.omega,'rad/s'],['模块质量',j.mass,'kg']].map(([l,v,u])=>`<span>${esc(l)}<b>${v===null?'—':esc(numberText(v)+' '+u)}</b></span>`).join('')}</div><p class="joint-note">${esc(j.note||'具体参数边界见原始资料。')}</p><div class="source-pills"><a href="${esc(safeUrl(data.sources[j.source].url))}" target="_blank" rel="noopener noreferrer">${esc(j.source+' · '+j.locator)}${icon('arrow-up-right')}</a></div></article>`).join(''):`<div class="detail-empty">这条配置还没有经过核实的各轴执行器与传动记录。公开资料中的最大扭矩，不会自动当成已确认的整机关节型号。</div>`}`}
function evidenceContent(p){return `<h3 class="detail-section-title">原始资料与参数证据 <span>核查于 ${esc(data.asof)}</span></h3>${sourceIds(p).map(id=>{const s=data.sources[id];return `<article class="source-card"><h4><code>${esc(id)}</code>${esc(s.title)}</h4><p>${esc(s.kind)} · ${esc(s.version)}</p><p>原文位置：${esc(s.locator)}</p><a href="${esc(safeUrl(s.url))}" target="_blank" rel="noopener noreferrer">打开原始资料 ${icon('arrow-up-right')}</a></article>`}).join('')}<details class="evidence-details" open><summary>${Object.keys(p.metrics).length} 项已记录数值的详细出处</summary><table class="evidence-table"><thead><tr><th>指标</th><th>值</th><th>条件 / 原文位置</th></tr></thead><tbody>${Object.entries(p.metrics).map(([k,m])=>`<tr><td>${esc(data.metricDefs[k]?.[0]??k)}</td><td>${esc(boundText(m)+' '+(data.metricDefs[k]?.[1]??''))}</td><td>${esc(m.condition||m.qual)}<br><small>${esc(m.source+' · '+m.locator)}</small></td></tr>`).join('')}</tbody></table></details>`}
function renderDetail(){const p=byId.get(detailId);if(!p)return;const variants=records.filter(r=>familyKey(r)===familyKey(p));const im=imageFor(p);$('#detailContent').innerHTML=`<div class="dialog-top"><div><p class="eyebrow">${esc(p.brand)} / PLATFORM PROFILE</p><h2>${esc(titleFor(p))}</h2></div><button class="icon-button" type="button" data-close="detailDialog" aria-label="关闭平台详情">${icon('x')}</button></div><div class="detail-main"><div><div class="detail-hero-media ${im?.photo?'photo':''}">${imageHtml(p,'fetchpriority="high"')}</div><p class="photo-caption">${im?`${esc(im.caption)}<br>图片：<a href="${esc(safeUrl(im.pageUrl))}" target="_blank" rel="noopener noreferrer">${esc(im.credit)}</a>`:'这条历史记录暂未收录可核实的图片。'}</p><div class="detail-classifications"><span>${esc(p.type)}</span><span>${isResearch(p)?'科研平台':'商业 / 历史产品'}</span><span>${Object.keys(p.metrics).length}项数值证据</span></div></div><div><div class="detail-meta"><code>${esc(p.id)}</code><span>资料核查 ${esc(data.asof)}</span></div><p class="detail-position">${esc(p.position)}</p><div class="variant-field"><label for="detailVariant">${variants.length>1?'切换配置 / 资料版本':'当前配置 / 资料版本'} · ${variants.length} 条记录</label><select id="detailVariant">${variants.map(v=>`<option value="${esc(v.id)}" ${v.id===p.id?'selected':''}>${esc(v.variant)} · ${esc(v.id)}</option>`).join('')}</select></div><div class="detail-top-metrics">${metricHtml('整机质量',boundText(p.metrics.mass),'kg')}${metricHtml('公开载重',boundText(p.metrics.payload),'kg')}${metricHtml('披露速度',displaySpeed(p),'m/s')}${metricHtml('续航',runtimeText(p),'h')}</div></div></div><div class="detail-tabs" role="tablist" aria-label="详情内容">${[['spec','整机规格'],['joints','关节与传动'],['evidence','证据来源']].map(([key,l])=>`<button role="tab" type="button" data-tab="${key}" class="${detailTab===key?'active':''}" aria-selected="${detailTab===key}" aria-controls="detailTabBody" id="tab-${key}">${l}</button>`).join('')}</div><div class="detail-body" id="detailTabBody" role="tabpanel" aria-labelledby="tab-${detailTab}">${detailTab==='joints'?jointContent(p):detailTab==='evidence'?evidenceContent(p):specContent(p)}</div><div class="detail-actions"><button type="button" class="button button-outline copy-button" id="copyLink">${icon('link')}复制详情链接</button><button type="button" class="button ${compareIds.includes(p.id)?'button-outline':'button-primary'}" data-compare="${esc(p.id)}">${icon(compareIds.includes(p.id)?'check':'plus')}${compareIds.includes(p.id)?'已加入对比':'加入参数对比'}</button></div>`;}
function openDetail(id,{keepTab=false}={}){if(!byId.has(id))return;detailId=id;if(!keepTab)detailTab='spec';renderDetail();history.replaceState(null,'','#robot/'+encodeURIComponent(id));showDialog('detailDialog');}
function toggleCompare(id){if(compareIds.includes(id))compareIds=compareIds.filter(x=>x!==id);else{if(compareIds.length>=4){toast('一次最多对比 4 条配置');return;}compareIds.push(id);}render();renderCompareTray();if(detailId){const top=$('#detailDialog').scrollTop;renderDetail();$('#detailDialog').scrollTop=top;}}
function renderCompareTray(){$('#compareTray').hidden=compareIds.length===0;$('#compareCount').textContent=compareIds.length+' 个待比较';$('#compareNames').textContent=compareIds.map(id=>byId.get(id)?.family).join(' / ');$('#compareButton').disabled=compareIds.length<2;}
function compare(){if(compareIds.length<2)return;const ps=compareIds.map(id=>byId.get(id));const rows=[['质量 (kg)',p=>boundText(p.metrics.mass),''],['质量口径',p=>p.massBasis,'text-compare'],['公开载重 (kg)',p=>boundText(p.metrics.payload),''],['极限载重 (kg)',p=>boundText(p.metrics.payloadMax),''],['站立静载 (kg)',p=>boundText(p.metrics.static),''],['工作速度上限 (m/s)',p=>boundText(p.metrics.speed),''],['最高 / 演示速度 (m/s)',p=>boundText(p.metrics.speedPeak),''],['续航 (h)',p=>runtimeText(p),''],['续航工况',p=>p.runtimeBasis,'text-compare'],['带载试验负载 (kg)',p=>boundText(p.metrics.loadedMass),''],['带载续航下值 (h)',p=>boundText(p.metrics.loadedMin),''],['电池能量 (Wh)',p=>boundText(p.metrics.battery),''],['尺寸 (m)',p=>['length','width','height'].map(k=>boundText(p.metrics[k])).join(' × '),''],['尺寸口径',p=>p.sizeBasis,'text-compare'],['披露最大单轴扭矩 (N·m)',p=>boundText(p.metrics.torque),''],['防护等级',p=>p.ip,'text-compare'],['使用边界',p=>p.notes,'text-compare']];$('#compareContent').innerHTML=`<div class="comparison-note">相邻展示不代表测试条件相同。静载、极限值、名义能力与论文实测分别阅读。</div><div class="comparison-scroll"><table class="comparison-table"><thead><tr><th>性能指标</th>${ps.map(p=>`<th>${imageFor(p)?imageHtml(p):''}<h3>${esc(titleFor(p))}</h3><small>${esc(p.brand)}<br>${esc(p.variant)} · ${esc(p.id)}</small></th>`).join('')}</tr></thead><tbody>${rows.map(([label,fn,cls])=>`<tr><td>${esc(label)}</td>${ps.map(p=>`<td class="${cls}">${esc(fn(p))}</td>`).join('')}</tr>`).join('')}<tr><td>原始来源</td>${ps.map(p=>`<td><a class="button button-outline" target="_blank" rel="noopener noreferrer" href="${esc(safeUrl(data.sources[p.source].url))}">${esc(p.source)} ${icon('arrow-up-right')}</a></td>`).join('')}</tr></tbody></table></div>`;showDialog('compareDialog');}
function exportResults(){const ps=filterRecords(records,state);const headers=['ID','厂商','平台','配置','运动形态','质量_kg','质量口径','公开载重_kg','载重条件','最高披露速度_m_s','速度条件','续航下值_h','续航上值_h','续航工况','最大单轴扭矩_Nm','主来源URL'];const rows=ps.map(p=>[p.id,p.brand,p.family,p.variant,p.type,value(p,'mass'),p.massBasis,value(p,'payload'),p.metrics.payload?.condition??'',speedValue(p),(p.metrics.speedPeak??p.metrics.speed)?.condition??'',value(p,'runtimeMin'),value(p,'runtimeMax'),p.runtimeBasis,value(p,'torque'),data.sources[p.source].url]);const csv='\uFEFF'+[headers,...rows].map(r=>r.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(',')).join('\r\n');const u=URL.createObjectURL(new Blob([csvInLanguage(csv)],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download=getLanguage()==='en'?`RobotBodyAtlas_Quadrupeds_${ps.length}.csv`:`本体图鉴_四足筛选结果_${ps.length}配置.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast(`已导出 ${ps.length} 条匹配配置，保留具体版本`)}
document.addEventListener('click',async e=>{const open=e.target.closest('[data-open]');if(open){openDetail(open.dataset.open);return;}const comp=e.target.closest('[data-compare]');if(comp){toggleCompare(comp.dataset.compare);return;}const close=e.target.closest('[data-close]');if(close){closeDialog(close.dataset.close);return;}const view=e.target.closest('[data-view]');if(view){state.view=view.dataset.view;storeSet('atlas-view',state.view);render();return;}const scope=e.target.closest('[data-scope]');if(scope){state.scope=scope.dataset.scope;render();return;}const type=e.target.closest('[data-type]');if(type){state.type=type.dataset.type;render();return;}const chip=e.target.closest('[data-clear]');if(chip){removeChip(chip.dataset.clear);return;}const tab=e.target.closest('[data-tab]');if(tab){const top=$('#detailDialog').scrollTop;detailTab=tab.dataset.tab;renderDetail();$('#detailDialog').scrollTop=top;$('#tab-'+detailTab).focus();return;}if(e.target.closest('[data-reset]'))reset();if(e.target.closest('#copyLink')){try{await navigator.clipboard.writeText(location.href);toast('已复制当前配置的详情链接')}catch{toast('当前详情链接：'+location.href)}}});
document.addEventListener('change',e=>{const t=e.target;if(t.name==='brand'){t.checked?state.brands.add(t.value):state.brands.delete(t.value);render()}if(t.name==='category'){t.checked?state.categories.add(t.value):state.categories.delete(t.value);render()}if(t.id==='sortSelect'){state.sort=t.value;render()}if(t.id==='detailVariant')openDetail(t.value,{keepTab:true});});
$('#searchInput').addEventListener('input',e=>{state.query=e.target.value;render()});
for(const key of ['massMin','massMax','payloadMin','speedMin','runtimeMin'])$('#'+key).addEventListener('input',e=>{const n=e.target.valueAsNumber;state[key]=Number.isFinite(n)?n:null;render()});
$('#resetButton').addEventListener('click',reset);$('#exportButton').addEventListener('click',exportResults);$('#openFilters').addEventListener('click',()=>openFilters(true));$('#closeFilters').addEventListener('click',()=>openFilters(false));$('#filterShade').addEventListener('click',()=>openFilters(false));$('#clearCompare').addEventListener('click',()=>{compareIds=[];render();renderCompareTray()});$('#compareButton').addEventListener('click',compare);for(const id of ['methodButton','dataButton'])$('#'+id).addEventListener('click',()=>showDialog('methodDialog'));
$$('dialog').forEach(d=>{d.addEventListener('cancel',e=>{e.preventDefault();closeDialog(d.id)});d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog(d.id)}})});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$$('dialog').some(d=>d.open)){e.preventDefault();$('#searchInput').focus()}if(e.key==='Escape'&&$('#filterPanel').classList.contains('open'))openFilters(false);if(e.target.closest('[role=tab]')&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const tabs=['spec','joints','evidence'];detailTab=tabs[(tabs.indexOf(detailTab)+(e.key==='ArrowRight'?1:2))%3];renderDetail();$('#tab-'+detailTab).focus();}});
window.addEventListener('hashchange',()=>{const m=location.hash.match(/^#robot\/(.+)$/);if(m&&byId.has(decodeURIComponent(m[1])))openDetail(decodeURIComponent(m[1]));else if($('#detailDialog').open)closeDialog('detailDialog')});
try{const response=await fetch('data/library.json');if(!response.ok)throw Error('HTTP '+response.status);data=await response.json();records=data.platforms;byId=new Map(records.map(p=>[p.id,p]));$('#familyCount').textContent=groupRecords(records).length;$('#recordCount').textContent=records.length;$('#navCount').textContent=records.length;$('#sourceCount').textContent=Object.keys(data.sources).length;$('#asOf').textContent=data.asof.replaceAll('-','.');const metricCount=records.reduce((n,p)=>n+Object.keys(p.metrics).length,0);$('#methodStats').innerHTML=`<span><strong>${records.length}</strong>配置记录</span><span><strong>${metricCount}</strong>数值证据</span><span><strong>${data.joints.length}</strong>关节 / 传动</span><span><strong>${Object.keys(data.sources).length}</strong>原始资料</span>`;renderBrands();render();const m=location.hash.match(/^#robot\/(.+)$/);if(m)openDetail(decodeURIComponent(m[1]));}catch(error){console.error(error);$('#resultsContent').innerHTML=`<div class="empty-state">${icon('book')}<h3>资料暂未载入</h3><p>请刷新页面，重新载入平台库。</p><a class="button button-outline" href="./">重新载入</a></div>`;}
